
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_m05_2x_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_m05_2x", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.363101578321240e-02, -6.342192121803661e-02, -6.312372507833387e-02, -6.269948966332607e-02, -6.209649961944384e-02, -6.123352783597390e-02, -5.995221904540210e-02, -5.778193667399003e-02, -5.274832779664846e-02, -3.685055410454538e-02, -7.931837390618642e-03, -4.086721799209703e-02, -4.365556164723886e-02, -3.485596365316057e-02, -1.878460636715385e-02, 1.957381001256011e-02, 4.707558734639658e-02, 1.711390161705948e-02, 1.879307091368104e-03, 6.785616396511600e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


